#include "ark/spatial_sketch.hpp"
#include "ark/sketch.hpp"
#include "ark/serialize.hpp"
#include "ark/agent.hpp"
#include <cmath>
#include <iostream>
#include <stdexcept>
using namespace ark;using V=arkjson::Value;
static void check(bool ok,const char* message){if(!ok)throw std::runtime_error(message);}
static V parse(const char* text){V value;check(arkjson::parse(text,value),"Fixture JSON");return value;}
static void rejects(const V& spec,const Document& doc){bool rejected=false;try{solveSpatialCurve(spec,doc);}catch(const std::exception&){rejected=true;}check(rejected,"Invalid/conflicting 3D constraints must reject");}
int main(){try{
    Document doc;doc.setParam("Length","10");DatumPlane axis;axis.name="Travel";axis.kind="axis";axis.support=parse(R"JSON({"kind":"axis_points","start":[0,0,0],"end":[10,0,0]})JSON");doc.planes.push_back(axis);
    auto spec=parse(R"JSON({"start":[0,0,0],"segments":[{"kind":"line","to":[2,3,4]}],"constraints":[{"id":"origin","type":"fixed","point":"start","value":[0,0,0]},{"id":"axis","type":"on_axis","point":"segment.1.end","axis":"Travel"},{"id":"length","type":"distance","a":"start","b":"segment.1.end","value":"Length"}]})JSON");
    auto solved=solveSpatialCurve(spec,doc);const auto& end=solved.native.find("segments")->arr[0].find("to")->arr;check(std::abs(std::abs(end[0].num)-10)<1e-6&&std::abs(end[1].num)<1e-6&&std::abs(end[2].num)<1e-6,"3D distance/axis solution");check(solved.diagnostics.find("free_dofs")->num==0&&solved.diagnostics.find("rank")->num==6,"Full local rank and degrees of freedom");check(!solved.native.find("constraints")&&spec.find("constraints"),"Solved request never replaces authored constraint source");
    doc.setParam("Length","20");solved=solveSpatialCurve(spec,doc);check(std::abs(std::abs(solved.native.find("segments")->arr[0].find("to")->arr[0].num)-20)<1e-6,"Named 3D dimension recomputes");
    auto translated=parse(R"JSON({"start":["99999","0","0"],"segments":[{"kind":"line","to":[100000,0,0]},{"kind":"line","to":["100000","1","0"]}],"constraints":[{"type":"perpendicular","a":"start","b":"segment.1.end","c":"segment.1.end","d":"segment.2.end"}]})JSON");solved=solveSpatialCurve(translated,doc);check(solved.diagnostics.find("converged")->b&&solved.diagnostics.find("rank")->num==1,"Translated short directions retain valid finite differences and local rank");
    auto degen=translated;auto degenSegments=*degen.find("segments");degenSegments.arr[0].set("to",parse(R"JSON([99999,0,0])JSON"));degen.set("segments",degenSegments);rejects(degen,doc);
    auto phantom=parse(R"JSON({"start":["0","0","0"],"segments":[{"kind":"line","to":["10","0","0"],"through":[1,1,1]}],"constraints":[{"type":"fixed","point":"segment.1.through","value":[500,500,500]}]})JSON");rejects(phantom,doc);
    auto phantomPoles=translated;auto phantomSegments=*phantomPoles.find("segments");phantomSegments.arr[0].set("poles",parse(R"JSON([[99999,0,0],[100000,0,0]])JSON"));phantomPoles.set("segments",phantomSegments);rejects(phantomPoles,doc);
    auto under=parse(R"JSON({"start":[0,0,0],"segments":[{"kind":"line","to":[2,3,4]}],"constraints":[{"type":"distance","a":"start","b":"segment.1.end","value":5}]})JSON");solved=solveSpatialCurve(under,doc);check(solved.diagnostics.find("free_dofs")->num==5,"Underdetermined 3D sketch retains measured free motion");
    auto fixed=parse(R"JSON({"start":["0","0","0"],"segments":[{"kind":"line","to":["Length","0","0"]}],"constraints":[{"type":"distance","a":"start","b":"segment.1.end","value":"Length"}]})JSON");solved=solveSpatialCurve(fixed,doc);check(solved.diagnostics.find("variables")->num==0,"Expression coordinates are driven");fixed.set("constraints",parse(R"JSON([{"type":"distance","a":"start","b":"segment.1.end","value":3}])JSON"));rejects(fixed,doc);
    auto conflict=spec;auto constraints=*conflict.find("constraints");constraints.arr.push_back(parse(R"JSON({"type":"distance","a":"start","b":"segment.1.end","value":7})JSON"));conflict.set("constraints",constraints);rejects(conflict,doc);
    auto unknown=spec;constraints=*unknown.find("constraints");constraints.arr[0].set("point",V::makeStr("triangle.0"));unknown.set("constraints",constraints);rejects(unknown,doc);
    auto planar=parse(R"JSON({"start":["0","0","0"],"segments":[{"kind":"line","to":[4,2,7]}],"constraints":[{"type":"on_plane","point":"segment.1.end","plane":"XY"}]})JSON");solved=solveSpatialCurve(planar,doc);check(std::abs(solved.native.find("segments")->arr[0].find("to")->arr[2].num)<1e-6,"3D point stays on named plane");
    DatumPlane anchor;anchor.name="Anchor";anchor.kind="point";anchor.support=parse(R"JSON({"kind":"point","point":[3,4,5]})JSON");doc.planes.push_back(anchor);auto linked=parse(R"JSON({"start_ref":"Anchor","segments":[{"kind":"line","to":[8,4,5]}],"constraints":[{"type":"distance","a":"start","b":"segment.1.end","value":5}]})JSON");solved=solveSpatialCurve(linked,doc);check(!solved.native.find("start_ref")&&solved.native.find("start")->arr[2].num==5,"Associative point anchor is resolved as driven XYZ");
    auto angular=parse(R"JSON({"start":["0","0","0"],"segments":[{"kind":"line","to":["10","0","0"]},{"kind":"line","to":[12,6,2]}],"constraints":[{"type":"on_plane","point":"segment.2.end","plane":"XY"},{"type":"perpendicular","a":"start","b":"segment.1.end","c":"segment.1.end","d":"segment.2.end"},{"type":"distance","a":"segment.1.end","b":"segment.2.end","value":10}]})JSON");solved=solveSpatialCurve(angular,doc);auto p=solved.native.find("segments")->arr[1].find("to");check(std::abs(p->arr[0].num-10)<1e-6&&std::abs(std::abs(p->arr[1].num)-10)<1e-6&&std::abs(p->arr[2].num)<1e-6,"Perpendicular 3D segment and plane constraint");
#ifdef ARK_SPATIAL_NATIVE_TESTS
    AgentSession session;session.suppressIterationHistory();V args=parse(R"JSON({"commands":[{"op":"param.set","name":"Length","expr":10},{"op":"plane.set","name":"Travel","kind":"axis","support":{"kind":"axis_points","start":[0,0,0],"end":[10,0,0]}},{"op":"feature.add","type":"curve","name":"Constrained path"}]})JSON");auto commands=*args.find("commands");commands.arr[2].set("native",spec);args.set("commands",commands);args.set("expected_revision",V::makeNum((double)session.revision));auto out=session.call("doc_apply",args);check(!out.find("isError")->b,out.dump().c_str());auto report=session.call("native_inspect",parse(R"JSON({"id":1})JSON"));check(report.find("structuredContent")->find("report")->find("spatial_constraints")->find("converged")->b,"Native report retains 3D constraint diagnostics");const auto revision=session.revision;auto bad=parse(R"JSON({"commands":[{"op":"feature.edit","id":1}]})JSON");commands=*bad.find("commands");commands.arr[0].set("native",conflict);bad.set("commands",commands);bad.set("expected_revision",V::makeNum((double)revision));check(session.call("doc_apply",bad).find("isError")->b&&session.revision==revision,"Conflicting 3D edit rolls back atomically");Document restored;std::string error;check(documentFromJson(documentToJson(session.document,false,false),restored,&error)&&restored.find(1)->nativeSpec.find("constraints"),"Authored 3D constraints persist across roundtrip");
#endif
    std::cout<<"Spatial sketch constraints passed\n";return 0;
}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}
